```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // This is a simple example and may not handle all markdown cases
    // For a more robust solution, consider using a markdown parser library
    // like Pandoc or Markdown++.

    std::string html;
    std::stringstream ss(markdown);
    std::string line;

    while (std::getline(ss, line)) {
        html += line + "<br>";
    }

    return html;
}

int main() {
    std::string markdown = "# Heading\n\nThis is a paragraph.\n\nAnother paragraph.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

